 if(p.startsWith('/api/employee/')){if(req.method!=='GET'&&!employeeOriginOk(req))return json({ok:false,error:'origin_not_allowed'},403);if(p==='/api/employee/attendance'&&req.method==='GET')return empAttendance(req,env,url);if(p==='/api/employee/work-updates'&&(req.method==='GET'||req.method==='POST'))return empWorkUpdates(req,env);const wm=p.match(/^\/api\/employee\/work-updates\/([a-f0-9-]+)\/media\/([a-f0-9-]+)$/);if(wm&&req.method==='GET'){const ee=await employeeCurrent(req,env);return ee?empWorkMedia(env,ee,wm[1],wm[2]):json({ok:false,error:'unauthorized'},401);}if(p==='/api/employee/attendance-test'&&req.method==='POST')return empAttendanceTest(req,env);if(p==='/api/employee/check-in'&&req.method==='POST')return empPunch(req,env,false);if(p==='/api/employee/check-out'&&req.method==='POST')return empPunch(req,env,true);if(p==='/api/employee/leaves'&&req.method==='GET')return empLeaves(req,env);if(p==='/api/employee/leaves'&&req.method==='POST')return empApplyLeave(req,env);if(p==='/api/employee/password'&&req.method==='POST')return empPassword(req,env);return json({ok:false,error:'not_found'},404);}
